INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2073-2-item-1', 'hint-routine-2073-2', 'WORD', 'neighborhood', '동네', '집 근처에 도착한 뒤의 분위기를 말할 때 좋아요.', 'My neighborhood feels quiet in the evening.', 'INTRO_ROUTINE_HOME', 1, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
