INSERT INTO prompts (id, topic_detail_id, difficulty, question_en, question_ko, tip, display_order, is_active) VALUES ('prompt-preference-2212', @detail_preference_breakfast_meals_id, 'I', 'What is your favorite food to eat when you are in a hurry, and why do you like it?', '바쁠 때 먹기 좋은 음식 중에서 가장 좋아하는 것은 무엇이고, 왜 좋아하나요?', '좋아하는 음식과 그 이유를 한두 문장으로 말해 보세요.', 6147, 1) ON DUPLICATE KEY UPDATE topic_detail_id = VALUES(topic_detail_id), difficulty = VALUES(difficulty), question_en = VALUES(question_en), question_ko = VALUES(question_ko), tip = VALUES(tip), display_order = VALUES(display_order), is_active = VALUES(is_active);
