INSERT INTO prompts (id, topic_detail_id, difficulty, question_en, question_ko, tip, display_order, is_active) VALUES ('prompt-preference-2230', @detail_preference_snacks_sweets_id, 'I', 'What is your favorite small treat after a long day, and why do you like it?', '긴 하루 뒤 작은 보상처럼 먹기 좋은 간식 중에서 가장 좋아하는 것은 무엇이고, 왜 좋아하나요?', '가볍게 먹는 간식과 좋아하는 이유를 직접적으로 말해 보세요.', 6165, 1) ON DUPLICATE KEY UPDATE topic_detail_id = VALUES(topic_detail_id), difficulty = VALUES(difficulty), question_en = VALUES(question_en), question_ko = VALUES(question_ko), tip = VALUES(tip), display_order = VALUES(display_order), is_active = VALUES(is_active);
