INSERT INTO prompts (id, topic_detail_id, difficulty, question_en, question_ko, tip, display_order, is_active) VALUES ('prompt-preference-2320', @detail_preference_simple_places_id, 'I', 'What is your favorite nearby place when you want a little fresh air, and why do you like it?', '바람을 조금 쐬고 싶을 때 가기 좋은 가까운 곳 중에서 가장 좋아하는 것은 무엇이고, 왜 좋아하나요?', '가까운 장소를 떠올리고 편한 이유를 한두 가지 말해 보세요.', 6255, 1) ON DUPLICATE KEY UPDATE topic_detail_id = VALUES(topic_detail_id), difficulty = VALUES(difficulty), question_en = VALUES(question_en), question_ko = VALUES(question_ko), tip = VALUES(tip), display_order = VALUES(display_order), is_active = VALUES(is_active);
